# SECURE: scheme allowlist, resolved-IP checks, no redirects
import ipaddress
import socket
from urllib.parse import urlsplit

def safe_get(url: str) -> bytes:
    parts = urlsplit(url)
    if parts.scheme != 'https' or not parts.hostname:
        raise ValueError('https only')
    infos = socket.getaddrinfo(parts.hostname, 443, proto=socket.IPPROTO_TCP)
    for info in infos:
        if not ipaddress.ip_address(info[4][0]).is_global:
            raise ValueError('destination not allowed')
    return requests.get(url, timeout=5, allow_redirects=False).content

