# SECURE: HMAC over raw body and timestamp, constant-time compare
@app.post('/hooks/payments')
def hook():
    raw = request.get_data()
    ts = request.headers.get('X-Timestamp', '')
    try:
        if abs(time.time() - int(ts)) > 300:
            abort(401)
    except ValueError:
        abort(401)
    mac = hmac.new(SECRET, ts.encode() + b'.' + raw, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(mac, request.headers.get('X-Signature', '')):
        abort(401)
    process(json.loads(raw))

